window.__code__["budget-py-21"] = {"code_id": "budget-py-21", "kind": "src", "title": "_budget.py:21", "source_path": "agentscope/src/agentscope/middleware/_budget.py", "highlight_line": 21, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Budget control middleware for AgentScope agents.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> AsyncGenerator, Callable, TYPE_CHECKING</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..event <span class=\"c-kw\">import</span> ModelCallEndEvent, ReplyStartEvent, ReplyEndEvent</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..message <span class=\"c-kw\">import</span> AssistantMsg, HintBlock</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..tool <span class=\"c-kw\">import</span> ToolChoice</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._base <span class=\"c-kw\">import</span> MiddlewareBase</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">if</span> TYPE_CHECKING:</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ..agent <span class=\"c-kw\">import</span> Agent</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">_DEFAULT_HINT_MESSAGE = (</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&lt;system-reminder&gt;You have reached the maximum token budget set by the &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">    <span class=\"c-str\">&quot;user. Now you MUST wrap up immediately and provide a final &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">    <span class=\"c-str\">&quot;concluding response without invoking any tools.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&lt;/system-reminder&gt;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\"><span class=\"c-kw\">class</span> ReplyBudgetControlMiddleware(MiddlewareBase):</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Middleware that enforces a weighted token budget per reply.</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    Tracks cumulative weighted token usage across all reasoning steps within</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">    a single reply. The weighted cost <span class=\"c-kw\">is</span> computed <span class=\"c-kw\">as</span>::</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    cost = input_token_weight * input_tokens + output_token_weight * \\</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    output_tokens</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    Once the accumulated cost reaches ``token_budget``, a hint message <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    injected into the agent&<span class=\"c-com\">#x27;s context before the next reasoning step, and</span></span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">    ``tool_choice`` <span class=\"c-kw\">is</span> forced to ``<span class=\"c-str\">&quot;none&quot;</span>`` so the agent wraps up without</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    invoking any further tools.</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    Budget state <span class=\"c-kw\">is</span> stored <span class=\"c-kw\">in</span></span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    :attr:`~agentscope.agent.AgentState.middle_context`</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    keyed by the middleware key, so it persists across human-<span class=\"c-kw\">in</span>-the-loop (HITL)</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">    interruptions <span class=\"c-kw\">and</span> resumptions. State <span class=\"c-kw\">is</span> automatically cleaned up when the</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    reply ends via a :<span class=\"c-kw\">class</span>:`~agentscope.event.ReplyEndEvent`.</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">    .. note::</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">        The middleware <span class=\"c-kw\">is</span> stateless on the instance itself — all runtime state</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">        lives <span class=\"c-kw\">in</span> ``agent.state.middle_context``. This means the same middleware</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">        instance can safely be shared across multiple agents.</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    Example::</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">        <span class=\"c-kw\">from</span> agentscope.middleware <span class=\"c-kw\">import</span> BudgetControlMiddleware</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">        agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">            ...,</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">            middlewares=[</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">                BudgetControlMiddleware(</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">                    token_budget=10000,</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">                    input_token_weight=1.0,</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">                    output_token_weight=2.0,</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">            ],</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __init__(</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">        token_budget: float,</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">        input_token_weight: float = 1,</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        output_token_weight: float = 1,</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">        hint_message: str = _DEFAULT_HINT_MESSAGE,</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Initialize the budget control middleware.</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">            token_budget (`float`):</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">                Maximum weighted token cost allowed per reply. The cost <span class=\"c-kw\">for</span></span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">                each model call <span class=\"c-kw\">is</span> computed <span class=\"c-kw\">as</span></span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">                ``input_token_weight * input_tokens + output_token_weight *</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">                output_tokens``. Once the accumulated cost reaches this</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">                threshold, the agent <span class=\"c-kw\">is</span> instructed to wrap up without calling</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">                any more tools.</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">            input_token_weight (`float`, optional):</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">                Multiplier applied to input tokens when computing the</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">                weighted cost. Defaults to ``1``.</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">            output_token_weight (`float`, optional):</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">                Multiplier applied to output tokens when computing the</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">                weighted cost. Defaults to ``1``. Set this higher than</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">                ``input_token_weight`` to reflect that output tokens are</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">                typically more expensive.</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">            hint_message (`str`, optional):</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">                The message injected into the agent&<span class=\"c-com\">#x27;s context when the budget</span></span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">                <span class=\"c-kw\">is</span> exceeded. Defaults to a built-<span class=\"c-kw\">in</span> wrap-up prompt.</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.token_budget = token_budget</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.input_token_weight = input_token_weight</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.output_token_weight = output_token_weight</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.hint_message = hint_message</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reply(</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Manage per-reply budget state <span class=\"c-kw\">in</span> ``agent.state.middle_context``.</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">        Initializes the weighted cost counter <span class=\"c-kw\">for</span> the reply on</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`~agentscope.event.ReplyStartEvent`, accumulates cost on each</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`~agentscope.event.ModelCallEndEvent`, <span class=\"c-kw\">and</span> removes the entry on</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`~agentscope.event.ReplyEndEvent`.</span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">            agent (`Agent`):</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">                The agent instance executing this middleware.</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">            input_kwargs (`dict`):</span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">                Reply input kwargs (passed through unchanged).</span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">            next_handler (`Callable[..., AsyncGenerator]`):</span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">                Callable that executes the next middleware <span class=\"c-kw\">or</span> ``_reply``.</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">        Yields:</span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">            Events <span class=\"c-kw\">from</span> the reply process.</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">        middleware_key = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.get_middleware_key()</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> event <span class=\"c-kw\">in</span> next_handler(**input_kwargs):</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> isinstance(event, ReplyStartEvent):</span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">                <span class=\"c-com\"># Initialize the token counting number</span></span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> middleware_key <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> agent.state.middle_context:</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">                    agent.state.middle_context[middleware_key] = {}</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">                agent.state.middle_context[middleware_key][event.reply_id] = 0</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">            <span class=\"c-kw\">elif</span> isinstance(event, ReplyEndEvent):</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">                <span class=\"c-com\"># Clean up the token counting number</span></span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">                agent.state.middle_context[middleware_key].pop(</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">                    event.reply_id,</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">                    <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">            <span class=\"c-kw\">elif</span> isinstance(event, ModelCallEndEvent):</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">                <span class=\"c-com\"># Update the used tokens</span></span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> middleware_key <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> agent.state.middle_context:</span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">                    agent.state.middle_context[middleware_key] = {}</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">                agent.state.middle_context[middleware_key][event.reply_id] += (</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">                    <span class=\"c-kw\">self</span>.input_token_weight * event.input_tokens</span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">                    + <span class=\"c-kw\">self</span>.output_token_weight * event.output_tokens</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">            <span class=\"c-kw\">yield</span> event</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reasoning(</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Intercept each reasoning step to enforce the token budget.</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">        Before forwarding to the next handler, reads the accumulated weighted</span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">        cost <span class=\"c-kw\">for</span> the current reply <span class=\"c-kw\">from</span> ``agent.state.middle_context``. If the</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">        budget <span class=\"c-kw\">is</span> exhausted, appends a</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`~agentscope.message.HintBlock` to the last assistant message</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">        <span class=\"c-kw\">in</span> context (<span class=\"c-kw\">or</span> creates a new</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`~agentscope.message.AssistantMsg`) <span class=\"c-kw\">and</span> overrides</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        ``tool_choice`` to ``ToolChoice(mode=<span class=\"c-str\">&quot;none&quot;</span>)``.</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">            agent (`Agent`):</span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">                The agent instance executing this middleware.</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">            input_kwargs (`dict`):</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">                Dictionary containing ``tool_choice`` <span class=\"c-kw\">and</span> other reasoning</span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">                kwargs forwarded to the next handler.</span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">            next_handler (`Callable[..., AsyncGenerator]`):</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">                Callable that executes the next middleware <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">                ``_reasoning_impl``.</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">        Yields:</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">            Events <span class=\"c-kw\">from</span> the reasoning process.</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">        reply_id = agent.state.reply_id</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">        middleware_key = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.get_middleware_key()</span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">        used = agent.state.middle_context.get(</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">            middleware_key,</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">            {},</span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">        ).get(reply_id, 0)</span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">        <span class=\"c-com\"># Insert hint block if exceeded budget</span></span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> used &gt;= <span class=\"c-kw\">self</span>.token_budget:</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">            hint_block = HintBlock(hint=<span class=\"c-kw\">self</span>.hint_message)</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> (</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">                len(agent.state.context) &gt; 0</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">                <span class=\"c-kw\">and</span> agent.state.context[-1].role == <span class=\"c-str\">&quot;assistant&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">                <span class=\"c-kw\">and</span> agent.state.context[-1].name == agent.name</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">            ):</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">                agent.state.context[-1].content.append(hint_block)</span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">            <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">                agent.state.context.append(</span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">                    AssistantMsg(</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">                        id=agent.state.reply_id,</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">                        name=agent.name,</span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">                        content=[hint_block],</span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">                    ),</span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">            input_kwargs[<span class=\"c-str\">&quot;tool_choice&quot;</span>] = ToolChoice(mode=<span class=\"c-str\">&quot;none&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> event <span class=\"c-kw\">in</span> next_handler(**input_kwargs):</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">            <span class=\"c-kw\">yield</span> event</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 208, "explanation": "_budget.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [{"title": "Loop 治理（Loop Engineering）", "body": "StopGate 可插拔：DoomLoopGate（死循环）/BudgetGate（超预算）/IterationGate（超迭代）/FileLoopGate（文件循环）/RubricGate（评分不达标）各治一种失控，比单靠 max_iters 精准。"}, {"title": "预算控制中间件", "body": "ReplyBudgetControlMiddleware 代理回复预算，超即熔断；与 BudgetGate呼应，控单次回复 token。"}], "related_docs": ["W07-中间件记忆与上下文治理"]};
